import{_ as n,o as e,c as i,a3 as t}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"Pengaturan Tahun Ajaran & Profil Sekolah","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-admin/data-sekolah.md","filePath":"panduan-admin/data-sekolah.md","lastUpdated":null}'),r={name:"panduan-admin/data-sekolah.md"};function o(l,a,s,u,k,g){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="pengaturan-tahun-ajaran-profil-sekolah" tabindex="-1">Pengaturan Tahun Ajaran &amp; Profil Sekolah <a class="header-anchor" href="#pengaturan-tahun-ajaran-profil-sekolah" aria-label="Permalink to &quot;Pengaturan Tahun Ajaran &amp; Profil Sekolah&quot;">​</a></h1><p>Sebelum kegiatan akademik dan transaksi keuangan dimulai, Admin TU harus memastikan profil sekolah dan periode tahun ajaran aktif sudah diatur dengan benar.</p><hr><h2 id="_1-memeriksa-mengubah-profil-sekolah" tabindex="-1">1. Memeriksa &amp; Mengubah Profil Sekolah <a class="header-anchor" href="#_1-memeriksa-mengubah-profil-sekolah" aria-label="Permalink to &quot;1. Memeriksa &amp; Mengubah Profil Sekolah&quot;">​</a></h2><ol><li>Masuk ke menu <strong>Kelola (Manage)</strong> <strong>Pengaturan (Settings)</strong> <strong>Profil Sekolah</strong>.</li><li>Periksa informasi dasar: <ul><li><strong>Nama Resmi Sekolah</strong> (muncul pada kop surat dan kuitansi).</li><li><strong>NPSN &amp; Alamat Lengkap</strong>.</li><li><strong>Logo Sekolah</strong>: Unggah file PNG dengan latar belakang transparan agar kuitansi dan kop surat tercetak rapi.</li><li><strong>Tanda Tangan &amp; Cap Digital</strong>: Diunggah jika ingin fitur surat otomatis memiliki stempel basah digital.</li></ul></li><li>Klik tombol <strong>Simpan Perubahan</strong>.</li></ol><hr><h2 id="_2-menambah-mengaktifkan-tahun-ajaran-baru" tabindex="-1">2. Menambah &amp; Mengaktifkan Tahun Ajaran Baru <a class="header-anchor" href="#_2-menambah-mengaktifkan-tahun-ajaran-baru" aria-label="Permalink to &quot;2. Menambah &amp; Mengaktifkan Tahun Ajaran Baru&quot;">​</a></h2><p>Sistem menggunakan konsep <strong>Tahun Ajaran Aktif</strong>. Seluruh tagihan SPP, presensi, dan nilai rapor akan dikaitkan dengan tahun ajaran yang sedang aktif.</p><ol><li>Buka menu <strong>Kelola</strong> <strong>Tahun Ajaran (Academic Years)</strong>.</li><li>Klik tombol <strong>+ Tambah Tahun Ajaran</strong>.</li><li>Masukkan nama tahun ajaran (contoh: <code>2026/2027</code>).</li><li>Pilih status <strong>Semester</strong>: <ul><li>Ganjil (Juli - Desember)</li><li>Genap (Januari - Juni)</li></ul></li><li>Centang opsi <strong>Jadikan Periode Aktif</strong>.</li><li>Klik <strong>Simpan</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Perhatian Penting</p><p>Mengubah status tahun ajaran aktif ke periode baru akan otomatis mengalihkan pembukuan dan presensi kelas ke periode tersebut. Pastikan proses tutup buku atau pembagian rapor di periode sebelumnya sudah selesai.</p></div>',10)])])}const d=n(r,[["render",o]]);export{m as __pageData,d as default};
